export function refundableBalance(data: Data, customerId: string) {
  const customer = data.customers.find((c) => c.id === customerId);
  if (!customer) throw new UserError("Customer not found");
  let promo = 0;
  let cash = 0;
  const txs = data.walletTxs.filter((t) => t.customerId === customerId);
  for (const t of txs) {
    switch (t.type) {
      case "TOPUP": cash += t.amount; break;
      case "BONUS": case "REFERRAL_REWARD": promo += t.amount; break;
      case "REFERRAL_REVERSAL": { const take = Math.min(promo, -t.amount); promo -= take; cash -= (-t.amount - take); break; }
      case "SPEND": { const use = Math.min(promo, -t.amount); promo -= use; cash -= (-t.amount - use); break; }
      case "REFUND": cash += t.amount; break;
      case "CASHOUT": case "WRITE_OFF": promo = 0; cash = 0; break;
    }
  }
  const promoLeft = Math.min(customer.walletBalance, Math.max(0, promo));
  return { balance: customer.walletBalance, refundable: customer.walletBalance - promoLeft, promotional: promoLeft };
}

let loadFailed = false;
function persist() {
  if (loadFailed) return;
  if (saveTimer) clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    AsyncStorage.setItem(KEY, JSON.stringify(state)).catch((e) => console.warn("Could not save data", e));
  }, 150);
}

export async function loadStore(): Promise<void> {
  try {
    const raw = await AsyncStorage.getItem(KEY);
    let next = raw ? migrate(JSON.parse(raw)) : buildDemoData();
    const purged = purgeExpired(next);
    next = purged.data;
    applyCatalog(next);
    state = next;
    deletePhotos(purged.result.photoKeys).catch(() => {});
    persist();
  } catch (e) {
    console.warn("Could not load saved data", e);
    if (saveTimer) clearTimeout(saveTimer);
    loadFailed = true;
  }
  try {
    const rawSession = await AsyncStorage.getItem(SESSION_KEY);
    session = rawSession && !loadFailed ? (JSON.parse(rawSession) as Session) : null;
  } catch {
    session = null;
    AsyncStorage.removeItem(SESSION_KEY).catch(() => {});
  }
  ready = true;
  emit();
}
